INSERT INTO custom_facebrasil.waterfall_sessions ("id", "article_id", "tone", "angle", "audience", "data", "images", "created_at", "updated_at", "slide_images") VALUES
  ('bf0ec563-bf5c-4985-b5dd-278dbd1439bf', 'c211a0d5-104d-4b59-be51-47b40d5ca099', 'inspiracional', 'provocador', 'diaspora', '{"twitter": {"thread": [{"text": "🧠 Você já pensou em como suas decisões diárias são influenciadas pelas escolhas alheias? A Teoria dos Jogos, que rendeu um Nobel a John Nash, explica esse fenômeno! 🏆", "number": 1}, {"text": "No trabalho, você colabora ou compete? A escolha é sua, mas a Teoria dos Jogos explica as consequências! 💼", "number": 2}, {"text": "Conhece o \"Dilema do Prisioneiro\"? Mesmo quando a cooperação é melhor, muitos optam pela traição. 🤝", "number": 3}, {"text": "Brasileiros nos EUA vivem essas dinâmicas diariamente, mesmo sem perceber! 🇧🇷🇺🇸", "number": 4}, {"text": "Empreendedores enfrentam dilemas: baixar preços ou manter qualidade? 🤔", "number": 5}, {"text": "Decisões assertivas baseadas na Teoria dos Jogos podem transformar vidas. 🌟", "number": 6}, {"text": "Como você aplica a Teoria dos Jogos no seu cotidiano? 🗣️ 🔗 Link na bio @facebrasil", "number": 7}], "single_tweet": "Você está jogando o jogo certo? 🎲 A Teoria dos Jogos revela como decisões cotidianas são influenciadas pelos outros. Descubra mais! #TeoriaDosJogos"}, "facebook": {"story_post": "Você já se perguntou por que, em certas situações, fazemos escolhas que podem não parecer as melhores, mas que fazem sentido quando consideramos o que os outros vão fazer? Isso é a Teoria dos Jogos em ação! Essa teoria foi tão significativa que rendeu um Nobel de Economia a John Nash. Para nós, brasileiros nos EUA, essa teoria se aplica no trabalho, negócios e vida pessoal. Por exemplo, no trabalho, você pode escolher entre ajudar um colega ou focar apenas no seu desempenho, e essa decisão pode impactar a dinâmica de todo o ambiente. Nos negócios, escolher entre baixar preços ou manter qualidade são dilemas diários. Como isso aparece no seu dia a dia? Como você usa essas estratégias para tomar decisões? Compartilhe suas experiências nos comentários! 🤔🗣️", "engagement_post": "Você já usou a Teoria dos Jogos para tomar decisões no trabalho ou nos negócios? Como suas escolhas foram influenciadas pelas ações dos outros? Compartilhe suas experiências e participe da discussão sobre estratégias e decisões assertivas! 📈🤝"}, "instagram": {"caption": "Você já ouviu falar da Teoria dos Jogos? 🎲 Ela explica como nossas decisões são influenciadas pelas ações dos outros. De John Nash ao seu dia a dia nos EUA, descubra como aplicar essa teoria na sua vida! #TeoriaDosJogos #JohnNash #Decisões", "carousel": {"slides": [{"text": "Você já considerou como suas decisões diárias são influenciadas pelas escolhas dos outros? 🤔", "number": 1}, {"text": "A Teoria dos Jogos ajuda a entender essas escolhas. Foi Nobel para John Nash! 🏆", "number": 2}, {"text": "No trabalho, cooperar ou competir? Sua decisão pode mudar tudo! 💼", "number": 3}, {"text": "O famoso \"Dilema do Prisioneiro\" mostra: nem sempre escolhemos o melhor para todos! 🤝", "number": 4}, {"text": "Na comunidade brasileira nos EUA, essas dinâmicas aparecem no dia a dia. 🇧🇷🇺🇸", "number": 5}, {"text": "Empresas enfrentam dilemas: baixar preços ou manter qualidade? 🤔", "number": 6}, {"text": "Decisões assertivas podem transformar sua vida nos EUA. ✨", "number": 7}, {"text": "Como você aplica a Teoria dos Jogos no seu cotidiano? Compartilhe! 🗣️", "number": 8}, {"text": "- Estratégia importa
